Set-StrictMode -Version Latest
#!/usr/bin/env pwsh  <# .SYNOPSIS     BIZRA Genesis Node - Professional Elite Deployment Script (Windows PowerShell)  .DESCRIPTION     Enterprise-grade deployment automation with:     - Multi-environment support (dev/staging/prod)     - Blue-green deployment strategy     - Automated rollback capabilities     - Health checks and monitoring integration     - Security scanning and compliance checks     - Infrastructure as Code validation  .PARAMETER Phase     Deployment phase to execute (infrastructure, monitoring, build, deploy, quality, validate, backup, security, all)  .PARAMETER Environment     Target environment (development, staging, production)  .PARAMETER Region     AWS region for deployment  .PARAMETER ClusterName     Kubernetes cluster name  .PARAMETER Namespace     Kubernetes namespace  .PARAMETER Version     Application version to deploy  .EXAMPLE     .\deploy-professional.ps1 -Phase all -Environment production  .EXAMPLE     .\deploy-professional.ps1 -Phase deploy -Environment staging -Version "v1.2.3"  .NOTES     Requires PowerShell 7+ and appropriate AWS/Azure credentials #>  [CmdletBinding()] param(     [Parameter(Mandatory = $true)]     [ValidateSet("infrastructure", "monitoring", "build", "deploy", "quality", "validate", "backup", "security", "all")]     [string]$Phase,      [Parameter(Mandatory = $false)]     [ValidateSet("development", "staging", "production")]     [string]$Environment = "production",      [Parameter(Mandatory = $false)]     [string]$Region = "us-east-1",      [Parameter(Mandatory = $false)]     [string]$ClusterName = "bizra-genesis",      [Parameter(Mandatory = $false)]     [string]$Namespace = "bizra",      [Parameter(Mandatory = $false)]     [string]$Version = $(if ($env:GIT_COMMIT) { $env:GIT_COMMIT } else { git rev-parse --short HEAD 2>$null }),      [Parameter(Mandatory = $false)]     [string]$DockerRegistry = "bizragenesis" )  # ═══════════════════════════════════════════════════════════════════════ # CONFIGURATION # ═══════════════════════════════════════════════════════════════════════  # Script configuration $ErrorActionPreference = "Stop" $ProgressPreference = "SilentlyContinue"  # Colors for output (PowerShell compatible) $Colors = @{     Red = [ConsoleColor]::Red     Green = [ConsoleColor]::Green     Yellow = [ConsoleColor]::Yellow     Blue = [ConsoleColor]::Blue     Magenta = [ConsoleColor]::Magenta     Cyan = [ConsoleColor]::Cyan     White = [ConsoleColor]::White }  # Environment configurations $Environments = @{     development = @{         name = "development"         domain = "dev.bizra-genesis.com"         replicas = 2         resources = @{ cpu = "500m"; memory = "1Gi" }     }     staging = @{         name = "staging"         domain = "staging.bizra-genesis.com"         replicas = 3         resources = @{ cpu = "1000m"; memory = "2Gi" }     }     production = @{         name = "production"         domain = "api.bizra-genesis.com"         replicas = 5         resources = @{ cpu = "2000m"; memory = "4Gi" }     } }  # ═══════════════════════════════════════════════════════════════════════ # UTILITY FUNCTIONS # ═══════════════════════════════════════════════════════════════════════  function Write-ColorOutput {     param(         [string]$Message,         [ConsoleColor]$Color = [ConsoleColor]::White     )     Write-Host $Message -ForegroundColor $Color }  function Write-LogInfo {     param([string]$Message)     Write-ColorOutput "[$((Get-Date).ToString('yyyy-MM-dd HH:mm:ss'))] [INFO] $Message" $Colors.Blue }  function Write-LogSuccess {     param([string]$Message)     Write-ColorOutput "[$((Get-Date).ToString('yyyy-MM-dd HH:mm:ss'))] [SUCCESS] $Message" $Colors.Green }  function Write-LogWarning {     param([string]$Message)     Write-ColorOutput "[$((Get-Date).ToString('yyyy-MM-dd HH:mm:ss'))] [WARNING] $Message" $Colors.Yellow }  function Write-LogError {     param([string]$Message)     Write-ColorOutput "[$((Get-Date).ToString('yyyy-MM-dd HH:mm:ss'))] [ERROR] $Message" $Colors.Red }  function Write-Header {     param([string]$Title)     $separator = "=" * 80     Write-ColorOutput $separator $Colors.Magenta     Write-ColorOutput $Title $Colors.Cyan     Write-ColorOutput $separator $Colors.Magenta }  function Test-Dependencies {     Write-LogInfo "Validating deployment prerequisites..."      $dependencies = @(         @{ Name = "Docker"; Command = "docker --version" },         @{ Name = "Docker Compose"; Command = "docker-compose --version" },         @{ Name = "kubectl"; Command = "kubectl version --client" },         @{ Name = "Helm"; Command = "helm version" },         @{ Name = "Terraform"; Command = "terraform version" },         @{ Name = "AWS CLI"; Command = "aws --version" },         @{ Name = "Azure CLI"; Command = "az --version" },         @{ Name = "Google Cloud SDK"; Command = "gcloud --version" }     )      $missingDeps = @()      foreach ($dep in $dependencies) {         try {             $null = Invoke-Expression "$($dep.Command) 2>$null"         } catch {             $missingDeps += $dep.Name         }     }      if ($missingDeps.Count -gt 0) {         Write-LogError "Missing required dependencies: $($missingDeps -join ', ')"         exit 1     }      Write-LogSuccess "All dependencies validated" }  # ═══════════════════════════════════════════════════════════════════════ # INFRASTRUCTURE SETUP # ═══════════════════════════════════════════════════════════════════════  function Initialize-Infrastructure {     Write-Header "🏗️  INFRASTRUCTURE SETUP"      Write-LogInfo "Initializing Terraform..."     Push-Location "infrastructure/terraform"      try {         terraform init         terraform plan -var="environment=$Environment" -var="region=$Region"         terraform apply -auto-approve -var="environment=$Environment" -var="region=$Region"     } finally {         Pop-Location     }      Write-LogSuccess "Infrastructure setup complete" }  function Initialize-Kubernetes {     Write-Header "☸️  KUBERNETES CLUSTER SETUP"      Write-LogInfo "Configuring kubectl..."     aws eks update-kubeconfig --region $Region --name $ClusterName      Write-LogInfo "Creating namespace..."     kubectl create namespace $Namespace --dry-run=client -o yaml | kubectl apply -f -      Write-LogInfo "Installing cert-manager..."     kubectl apply -f "https://github.com/cert-manager/cert-manager/releases/download/v1.13.0/cert-manager.yaml"     kubectl wait --for=condition=available --timeout=300s deployment -n cert-manager --all      Write-LogInfo "Installing ingress-nginx..."     helm repo add ingress-nginx "https://kubernetes.github.io/ingress-nginx"     helm repo update     helm upgrade --install ingress-nginx ingress-nginx/ingress-nginx `         --namespace ingress-nginx --create-namespace `         --set controller.service.type=LoadBalancer      Write-LogSuccess "Kubernetes setup complete" }  # ═══════════════════════════════════════════════════════════════════════ # MONITORING STACK DEPLOYMENT # ═══════════════════════════════════════════════════════════════════════  function Deploy-Monitoring {     Write-Header "📊 MONITORING STACK DEPLOYMENT"      Write-LogInfo "Adding Helm repositories..."     helm repo add prometheus-community "https://prometheus-community.github.io/helm-charts"     helm repo add grafana "https://grafana.github.io/helm-charts"     helm repo add jaegertracing "https://jaegertracing.github.io/helm-charts"     helm repo add grafana "https://grafana.github.io/helm-charts"     helm repo update      Write-LogInfo "Deploying Prometheus stack..."     helm upgrade --install prometheus prometheus-community/kube-prometheus-stack `         --namespace monitoring --create-namespace `         --values "k8s/monitoring/prometheus-values.yaml" `         --wait      Write-LogInfo "Deploying Grafana..."     helm upgrade --install grafana grafana/grafana `         --namespace monitoring `         --values "k8s/monitoring/grafana-values.yaml" `         --wait      Write-LogInfo "Deploying Jaeger..."     helm upgrade --install jaeger jaegertracing/jaeger `         --namespace monitoring `         --values "k8s/monitoring/jaeger-values.yaml" `         --wait      Write-LogInfo "Deploying Loki stack..."     helm upgrade --install loki grafana/loki-stack `         --namespace monitoring `         --values "k8s/monitoring/loki-values.yaml" `         --wait      Write-LogSuccess "Monitoring stack deployed" }  # ═══════════════════════════════════════════════════════════════════════ # APPLICATION DEPLOYMENT # ═══════════════════════════════════════════════════════════════════════  function Build-AndPush {     Write-Header "🐳 BUILDING AND PUSHING CONTAINER IMAGES"      Write-LogInfo "Building application image..."     $imageTag = "$DockerRegistry/bizra-genesis-node:$Version"     $latestTag = "$DockerRegistry/bizra-genesis-node:latest"      docker build -t $imageTag -t $latestTag `                  --build-arg BUILDKIT_INLINE_CACHE=1 `                  --cache-from $latestTag `                  .      Write-LogInfo "Pushing images to registry..."     docker push $imageTag     docker push $latestTag      # Store for deployment     $script:CurrentImageTag = $imageTag     Write-LogSuccess "Container images built and pushed: $imageTag" }  function Deploy-Application {     Write-Header "🚀 DEPLOYING APPLICATION"      Write-LogInfo "Deploying to Kubernetes..."      # Update deployment with new image version     $deploymentFile = "k8s/app/deployment.yaml"     (Get-Content $deploymentFile) -replace 'image:.*', "image: $script:CurrentImageTag" |         Set-Content $deploymentFile      kubectl apply -f "k8s/app/" -n $Namespace      Write-LogInfo "Waiting for rollout to complete..."     kubectl rollout status "deployment/bizra-genesis-node" -n $Namespace --timeout=600s      Write-LogInfo "Setting up ingress..."     kubectl apply -f "k8s/ingress/" -n $Namespace      Write-LogSuccess "Application deployed successfully" }  # ═══════════════════════════════════════════════════════════════════════ # QUALITY ASSURANCE # ═══════════════════════════════════════════════════════════════════════  function Run-QualityChecks {     Write-Header "🔍 QUALITY ASSURANCE"      Write-LogInfo "Running security scans..."     # Run Trivy security scan     docker run --rm -v /var/run/docker.sock:/var/run/docker.sock `         aquasecurity/trivy:latest image `         --exit-code 1 `         --no-progress `         $script:CurrentImageTag      Write-LogInfo "Running performance tests..."     # Run k6 load tests     docker run --rm -v "$(Get-Location)/k6:/k6" `         grafana/k6:latest run `         --out json=/k6/results.json `         /k6/scenarios/api-slo.js      Write-LogInfo "Validating SLOs..."     # Check SLO compliance     kubectl exec -n monitoring deployment/prometheus-kube-prometheus-prometheus -- `         promtool check rules /etc/prometheus/prometheus.yml      Write-LogSuccess "Quality checks passed" }  # ═══════════════════════════════════════════════════════════════════════ # OBSERVABILITY VALIDATION # ═══════════════════════════════════════════════════════════════════════  function Validate-Observability {     Write-Header "📈 VALIDATING OBSERVABILITY"      $envConfig = $Environments[$Environment]      Write-LogInfo "Checking Prometheus targets..."     kubectl exec -n monitoring deployment/prometheus-kube-prometheus-prometheus -- `         wget -qO- http://localhost:9090/api/v1/targets | jq '.data.activeTargets[].health' | Select-String -Pattern "up" -Quiet      Write-LogInfo "Checking Grafana dashboards..."     $grafanaPassword = kubectl get secret --namespace monitoring grafana -o jsonpath="{.data.admin-password}" | base64 --decode     $response = curl -s -u "admin:$grafanaPassword" "http://localhost:3000/api/health"     if ($response -notmatch '"ok"') {         throw "Grafana health check failed"     }      Write-LogInfo "Checking Jaeger traces..."     $traces = curl -s "http://localhost:16686/api/services" | jq '.data[]' | Select-String -Pattern "bizra-genesis-node" -Quiet     if (-not $traces) {         throw "Jaeger traces check failed"     }      Write-LogInfo "Validating metrics collection..."     kubectl exec -n $Namespace deployment/bizra-genesis-node -- `         wget -qO- http://localhost:9090/metrics | Select-String -Pattern "business_value" -Quiet      Write-LogSuccess "Observability validation complete" }  # ═══════════════════════════════════════════════════════════════════════ # BACKUP AND DISASTER RECOVERY # ═══════════════════════════════════════════════════════════════════════  function Setup-Backup {     Write-Header "💾 BACKUP & DISASTER RECOVERY"      Write-LogInfo "Setting up Velero for backup..."     helm repo add vmware-tanzu "https://vmware-tanzu.github.io/helm-charts"     helm repo update      helm upgrade --install velero vmware-tanzu/velero `         --namespace velero --create-namespace `         --values "k8s/backup/velero-values.yaml" `         --wait      Write-LogInfo "Creating backup schedule..."     velero create schedule daily-backup `         --schedule="0 2 * * *" `         --include-namespaces="$Namespace,monitoring" `         --ttl=168h      Write-LogInfo "Setting up disaster recovery runbooks..."     # Copy runbooks to accessible location     Copy-Item "docs/ops/disaster-recovery.md" "/tmp/" -Force     Copy-Item "docs/ops/backup-restore.md" "/tmp/" -Force      Write-LogSuccess "Backup and DR setup complete" }  # ═══════════════════════════════════════════════════════════════════════ # PERFORMANCE OPTIMIZATION # ═══════════════════════════════════════════════════════════════════════  function Optimize-Performance {     Write-Header "⚡ PERFORMANCE OPTIMIZATION"      Write-LogInfo "Running performance benchmarks..."     kubectl exec -n $Namespace deployment/bizra-genesis-node -- `         cargo bench --all-features      Write-LogInfo "Analyzing performance metrics..."     # Compare against baselines     node scripts/performance-regression-detector.mjs      Write-LogInfo "Applying performance optimizations..."     # Auto-scale based on metrics     kubectl autoscale deployment bizra-genesis-node `         --cpu-percent=70 `         --min=3 `         --max=10 `         -n $Namespace      Write-LogSuccess "Performance optimization complete" }  # ═══════════════════════════════════════════════════════════════════════ # COMPLIANCE & SECURITY # ═══════════════════════════════════════════════════════════════════════  function Setup-Security {     Write-Header "🔒 SECURITY AND COMPLIANCE"      Write-LogInfo "Setting up network policies..."     kubectl apply -f "k8s/security/network-policies.yaml" -n $Namespace      Write-LogInfo "Configuring RBAC..."     kubectl apply -f "k8s/security/rbac.yaml" -n $Namespace      Write-LogInfo "Setting up secrets management..."     # Install external-secrets or similar     helm repo add external-secrets "https://charts.external-secrets.io"     helm repo update      helm upgrade --install external-secrets external-secrets/external-secrets `         --namespace external-secrets --create-namespace `         --wait      Write-LogInfo "Running compliance checks..."     # Run CIS Kubernetes benchmark     kubectl apply -f "https://raw.githubusercontent.com/aquasecurity/kube-bench/main/job.yaml"     kubectl wait --for=condition=complete job/kube-bench -n default --timeout=300s      Write-LogSuccess "Security and compliance setup complete" }  # ═══════════════════════════════════════════════════════════════════════ # MAIN DEPLOYMENT ORCHESTRATION # ═══════════════════════════════════════════════════════════════════════  function Invoke-FullDeployment {     Write-Header "🚀 BIZRA GENESIS NODE - PROFESSIONAL ELITE DEPLOYMENT"     Write-Output "Environment: $Environment"     Write-Output "Region: $Region"     Write-Output "Version: $Version"     Write-Output ""      # Pre-flight checks     Test-Dependencies      # Phase 1: Infrastructure     Initialize-Infrastructure     Initialize-Kubernetes      # Phase 2: Monitoring & Observability     Deploy-Monitoring      # Phase 3: Application     Build-AndPush     Deploy-Application      # Phase 4: Quality Assurance     Run-QualityChecks      # Phase 5: Validation     Validate-Observability      # Phase 6: Operational Excellence     Setup-Backup     Optimize-Performance     Setup-Security      # Final status     Write-Header "✅ DEPLOYMENT COMPLETE"     Write-Output "🎯 Application deployed successfully!"     Write-Output "📊 Monitoring: http://grafana.local"     Write-Output "📈 Metrics: http://prometheus.local"     Write-Output "🔍 Traces: http://jaeger.local"     Write-Output "📋 Logs: http://loki.local"     Write-Output "🌐 Application: http://app.local"     Write-Output ""     Write-Output "📞 Alert Contacts:"     Write-Output "   • PagerDuty: Configured for critical alerts"     Write-Output "   • Slack: #bizra-alerts channel"     Write-Output "   • Email: ops@bizra.com"     Write-Output ""     Write-Output "📚 Runbooks:"     Write-Output "   • Deployment: docs/ops/deployment.md"     Write-Output "   • Troubleshooting: docs/ops/troubleshooting.md"     Write-Output "   • Scaling: docs/ops/scaling.md" }  # ═══════════════════════════════════════════════════════════════════════ # SCRIPT EXECUTION # ═══════════════════════════════════════════════════════════════════════  try {     switch ($Phase) {         "infrastructure" { Initialize-Infrastructure }         "monitoring" { Deploy-Monitoring }         "build" { Build-AndPush }         "deploy" { Deploy-Application }         "quality" { Run-QualityChecks }         "validate" { Validate-Observability }         "backup" { Setup-Backup }         "security" { Setup-Security }         "all" { Invoke-FullDeployment }         default {             Write-LogError "Invalid phase: $Phase"             Write-Output "Usage: .\deploy-professional.ps1 -Phase `<phase>` [-Environment `<env>`] [-Region `<region>`]"             Write-Output "Phases: infrastructure, monitoring, build, deploy, quality, validate, backup, security, all"             exit 1         }     } } catch {     Write-LogError "Deployment failed: $($_.Exception.Message)"     exit 1 }
